// ICSE 9 Mathematics ch01 Rational and Irrational Numbers — practice bank with independent re-solve checks.
// Option values, keys and answers are typed as literals here; each check recomputes them with surd.mjs (exact
// arithmetic on p + q sqrt(c): simplification, rationalisation, parsing of every typed working line) or with
// integer long division for decimals. Proof items are qualitative: they carry a note and assert the facts they use.
import { Q, mk, r } from './lib.mjs';
import { V, tex, chain, sq, rat, fr, expansion, fromRecurring, terminates, dist, near } from './surd.mjs';
import { rootFig } from './figs.mjs';

const J = (lines) => lines.join('\n\n');
const O = (a) => a.map((s) => `$${s}$`);
const val = (s) => (typeof s === 'string' ? V(s) : s);
/** Option expressions typed as TeX: exactly one equals the target (compared as canonical exact forms). */
const WN = (C, opts, target) => C.which(opts.map((s) => tex(V(s))), tex(val(target)));
const ratOf = ([n, d]) => rat(n, d);
const parity = (n) => n % 2 === 0;
const hasPeriod = (s, maxP) => { for (let p = 1; p <= maxP; p++) { let ok = true; for (let i = 0; i + p < s.length; i++) if (s[i] !== s[i + p]) { ok = false; break; } if (ok) return p; } return 0; };
/** digits after the point of 0.4 3 4 33 4 333 4 3333 ... (a lone 4, then blocks of 3s one longer each time) */
const growing = (sep, run, n) => { let s = ''; for (let k = 0; s.length < n; k++) s += sep + run.repeat(k); return s.slice(0, n); };

const fig2 = rootFig({ a: 1, b: 1, alt: 'Number line with zero, one and two marked. At the point one a vertical segment of length one is drawn up to point B. A circle centred at zero passes through B and cuts the number line at the point labelled root two, between one and two.', caption: 'A unit right triangle: $OB = \\sqrt{2}$, and the circle with centre $O$ and radius $OB$ meets the line at $P$.' });
const fig5 = rootFig({ a: 2, b: 1, alt: 'Number line with zero, one, two and three marked. At the point two a vertical segment of length one is drawn up to point B. A circle centred at zero passes through B and cuts the number line at the point labelled root five, between two and three.', caption: 'A right triangle with legs $2$ and $1$: $OB = \\sqrt{5}$, and the circle with centre $O$ and radius $OB$ meets the line at $P$.' });

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: r`Meena says that every integer $n$ is a rational number. Which form of $n$ shows why?`, opts: O([r`\dfrac{n}{1}`, r`\dfrac{1}{n}`, r`\sqrt{n}`, r`0.\overline{n}`]), key: 'a', sol: r`A rational number is a quotient of two integers with a non-zero denominator. Writing $n = \dfrac{n}{1}$ does exactly that, for $n = -7$, $0$ or $12$ alike. The reciprocal $\dfrac{1}{n}$ fails at $n = 0$.`, d: 1, c: 'recall', t: [1], time: 45 }), (C) => { C.assert([-7, 0, 12].every((n) => V(`\\dfrac{${n}}{1}`).eq(rat(n)) && V(`\\dfrac{${n}}{1}`).rational), 'n/1 equals n and is rational'); C.key('a'); });

Q('m02', mk.mcq({ stem: r`A tailor writes the number $-\dfrac{12}{4}$ on a measuring slip. Which is the smallest of these sets that contains it?`, opts: ['natural numbers', 'whole numbers', 'integers', 'rational numbers that are not integers'], key: 'c', sol: r`$-\dfrac{12}{4} = -3$. It is negative, so it is neither natural nor whole; it is an integer, and every integer is rational.`, d: 1, c: 'understanding', t: [1], time: 45 }), (C) => { const x = fr(-12, 4); C.assert(x[1] === 1 && x[0] === -3 && x[0] < 0, 'value -3: a negative integer'); C.key('c'); });

Q('m03', mk.mcq({ stem: r`A tile shop sells edging strips whose lengths are fractions of a metre. Exactly one of these lengths, in metres, is a terminating decimal. Which one?`, opts: O([r`\dfrac{9}{14}`, r`\dfrac{11}{60}`, r`\dfrac{13}{80}`, r`\dfrac{4}{15}`]), key: 'c', sol: r`In lowest terms, a fraction terminates only if its denominator has no prime factor other than $2$ and $5$. $80 = 2^4 \times 5$ qualifies, and $\dfrac{13}{80} = 0.1625$. But $14$ has the factor $7$, and $60$ and $15$ have the factor $3$.`, d: 2, c: 'understanding', t: [1], time: 75 }), (C) => { C.which([[9, 14], [11, 60], [13, 80], [4, 15]].map(([n, d]) => terminates(n, d)), true); const e = expansion(13, 80); C.assert(e.pre === '1625' && e.rep === '', '13/80 = 0.1625'); });

Q('m04', mk.mcq({ stem: r`Which of the following decimals is an irrational number?`, opts: O([r`0.\overline{45}`, r`3.1\overline{27}`, r`0.434334333433334\ldots \text{ (each block of 3s is one longer than the last, split by single 4s)}`, r`0.5625`]), key: 'c', sol: r`$0.\overline{45}$ and $3.1\overline{27}$ repeat a block, and $0.5625$ stops, so each is rational. In $0.434334333\ldots$ the run of $3$s grows for ever, so no block repeats and it never stops: it is irrational.`, d: 3, c: 'analysis', t: [1], time: 90 }), (C) => {
  const s = growing('4', '3', 700);
  C.assert(hasPeriod(s, 120) === 0, 'growing pattern has no repeating block up to length 120');
  C.assert(fromRecurring(0, '', '45')[1] === 11 && fromRecurring(3, '1', '27')[1] > 0 && expansion(9, 16).rep === '' && expansion(9, 16).pre === '5625', 'the other three are rational');
  C.key('c');
});

const m05o = [r`\sqrt{12} + \sqrt{3}`, r`(\sqrt{12} + \sqrt{3})^2`, r`\sqrt{12} \times \sqrt{5}`, r`\dfrac{\sqrt{12}}{\sqrt{5}}`];
Q('m05', mk.mcq({ stem: r`Rani combines the surds $\sqrt{12}$, $\sqrt{3}$ and $\sqrt{5}$ in four different ways. Which result is a rational number?`, opts: O(m05o), key: 'b', sol: r`$\sqrt{12} + \sqrt{3} = 3\sqrt{3}$ is irrational. Squaring it gives $9 \times 3 = 27$, which is rational. $\sqrt{12} \times \sqrt{5} = 2\sqrt{15}$ and $\dfrac{\sqrt{12}}{\sqrt{5}} = \dfrac{2\sqrt{15}}{5}$ are irrational.`, d: 3, c: 'analysis', t: [1, 4], time: 90 }), (C) => { C.which(m05o.map((s) => V(s).rational), true); C.assert(V(m05o[1]).eq(rat(27)), '27'); });

const m06o = [r`\dfrac{3}{11}`, r`\dfrac{27}{100}`, r`\dfrac{27}{90}`, r`\dfrac{9}{11}`];
Q('m06', mk.mcq({ stem: r`A label on a fabric roll gives the width as $0.272727\ldots$ metres, that is $0.\overline{27}$ m. In lowest terms, this width is`, opts: O(m06o), key: 'a', sol: r`Let $x = 0.\overline{27}$. Then $100x = 27.\overline{27}$, so $99x = 27$ and $x = \dfrac{27}{99} = \dfrac{3}{11}$. The fraction $\dfrac{27}{100}$ would be $0.27$, which stops.`, d: 2, c: 'understanding', t: [1], time: 75 }), (C) => { WN(C, m06o, ratOf(fromRecurring(0, '', '27'))); C.assert(expansion(3, 11).rep === '27', '3/11 = 0.2727...'); });

const m07o = [r`\dfrac{1}{6}`, r`\dfrac{16}{99}`, r`\dfrac{1}{60}`, r`\dfrac{8}{45}`];
Q('m07', mk.mcq({ stem: r`A tank gauge shows $0.1666\ldots$, that is $0.1\overline{6}$, of full capacity. As a fraction in lowest terms this is`, opts: O(m07o), key: 'a', sol: r`Let $x = 0.1\overline{6}$. Then $10x = 1.\overline{6}$ and $100x = 16.\overline{6}$. Subtracting, $90x = 15$, so $x = \dfrac{15}{90} = \dfrac{1}{6}$. The fraction $\dfrac{16}{99}$ treats the $1$ as repeating too.`, d: 3, c: 'application', t: [1], time: 90 }), (C) => { WN(C, m07o, ratOf(fromRecurring(0, '1', '6'))); const e = expansion(1, 6); C.assert(e.pre === '1' && e.rep === '6', '1/6 = 0.1666...'); });

Q('m08', mk.mcq({ stem: r`To prove by contradiction that $\sqrt{2}$ is irrational, we begin by assuming that`, opts: O([r`\sqrt{2} = \dfrac{p}{q}, \text{ where } p, q \text{ are integers with no common factor except } 1, q \ne 0`, r`\sqrt{2} \text{ is a terminating decimal}`, r`\sqrt{2} \text{ is a whole number}`, r`p^2 = 2q^2 \text{ has no integer solutions}`]), key: 'a', sol: r`A proof by contradiction assumes the opposite of what we want: $\sqrt{2}$ is rational, so it can be written in lowest terms as $\dfrac{p}{q}$. We then show that this leads to a contradiction.`, d: 1, c: 'recall', t: [2], time: 60 }), null, 'Qualitative recall of the start of the proof: the assumption is the negation of the claim, written in lowest terms.');

Q('m09', mk.mcq({ stem: r`In the proof that $\sqrt{2}$ is irrational we reach $p^2 = 2q^2$, where $p$ and $q$ are integers. Which conclusion is correct?`, opts: ['$p^2$ is even, so $p$ is even', '$p^2$ is even, so $p$ is odd', '$q$ is even, so $p$ is odd', '$p^2$ is odd, so $p$ is even'], key: 'a', sol: r`The right side $2q^2$ is a multiple of $2$, so $p^2$ is even. The square of an odd number is odd, so $p$ cannot be odd: $p$ is even.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const ns = Array.from({ length: 60 }, (_, i) => i + 1); C.assert(ns.every((n) => parity(n * n) === parity(n)), 'n squared and n have the same parity'); C.key('a'); }, 'The key follows from: the square of an odd number is odd (asserted for 1..60).');

Q('m10', mk.mcq({ stem: r`Isha copies the proof for $\sqrt{2}$ word for word to "show" that $\sqrt{4}$ is irrational. Which is the first line of her argument that is not valid?`, opts: ['Suppose $\\sqrt{4} = \\dfrac{p}{q}$ with $p$ and $q$ having no common factor.', 'Squaring, $p^2 = 4q^2$, so $p^2$ is even and $p$ is even.', 'Write $p = 2k$. Then $4k^2 = 4q^2$, so $q$ is even too, which contradicts the assumption.', 'Hence $\\sqrt{4}$ is irrational.'], key: 'c', sol: r`With $p = 2k$ we get $4k^2 = 4q^2$, that is $q = k$, which need not be even. Indeed $p = 2$, $q = 1$ has no common factor and gives $\sqrt{4} = 2$. The "q is even too" line is the first to fail.`, d: 4, c: 'analysis', t: [2], time: 120 }), (C) => { const p = 2, q = 1; C.assert(p * p === 4 * q * q && p / q === Math.sqrt(4) && q % 2 === 1 && p % 2 === 0, 'p = 2, q = 1 satisfies every earlier line but q is odd'); C.key('c'); }, 'Counter-example p = 2, q = 1 (asserted): the first three lines are all true for it, so the failure is the claim that q is even.');

const m11 = dist([0, 0], [4, 3]);
Q('m11', mk.mcq({ stem: r`Kavya marks $O$ at $0$ and $A$ at $4$ on a number line. At $A$ she draws a segment $AB$ of length $3$ at right angles to the line, then places a compass point at $O$ with radius $OB$ and cuts the line at $P$. Which number does $P$ represent?`, opts: O([r`5`, r`7`, r`\sqrt{7}`, r`\sqrt{12}`]), key: 'a', sol: r`By Pythagoras, $OB^2 = 4^2 + 3^2 = 25$, so $OB = 5$. The compass copies this length on to the line, so $P$ is at $5$. It is a rational number, because $25$ is a perfect square.`, d: 3, c: 'analysis', t: [3], time: 90 }), (C) => { C.which([5, 7, Math.sqrt(7), Math.sqrt(12)], m11); });

const m12 = [[2, 2], [1, 2], [3, 2], [3, 1]];
Q('m12', mk.mcq({ stem: r`To mark $\sqrt{10}$ on the number line by the right-triangle construction, with $OA$ along the line and $AB$ at right angles, which pair of whole-number lengths should be used?`, opts: m12.map(([a, b]) => `$OA = ${a}$ and $AB = ${b}$`), key: 'd', sol: r`We need $OA^2 + AB^2 = 10$. The pair $3$ and $1$ gives $9 + 1 = 10$. The other pairs give $8$, $5$ and $13$.`, d: 2, c: 'application', t: [3], time: 75 }), (C) => { C.which(m12.map(([a, b]) => a * a + b * b), 10); });

Q('m13', mk.mcq({ stem: r`Which description correctly locates $\dfrac{7}{4}$ on the number line?`, opts: ['Divide the interval from $1$ to $2$ into four equal parts and take the third mark from $1$.', 'Divide the interval from $1$ to $2$ into seven equal parts and take the fourth mark from $1$.', 'Divide the interval from $0$ to $1$ into four equal parts and take the third mark from $0$.', 'Divide the interval from $2$ to $3$ into four equal parts and take the first mark from $2$.'], key: 'a', sol: r`$\dfrac{7}{4} = 1 + \dfrac{3}{4}$, so it is three quarters of the way from $1$ to $2$. The other descriptions give $1\dfrac{4}{7}$, $\dfrac{3}{4}$ and $2\dfrac{1}{4}$.`, d: 2, c: 'understanding', t: [3], time: 75 }), (C) => { C.which([1 + 3 / 4, 1 + 4 / 7, 3 / 4, 2 + 1 / 4], 7 / 4); });

const m14 = [r`\sqrt{196}`, r`\sqrt{\dfrac{49}{81}}`, r`\sqrt{135}`, r`\sqrt{0.0016}`];
Q('m14', mk.mcq({ stem: r`A carpenter lists four lengths in metres. Exactly one of them is a surd. Which one?`, opts: O(m14), key: 'c', sol: r`$\sqrt{196} = 14$, $\sqrt{\dfrac{49}{81}} = \dfrac{7}{9}$ and $\sqrt{0.0016} = 0.04$ are all rational. But $135 = 9 \times 15$ is not a perfect square, so $\sqrt{135} = 3\sqrt{15}$ is irrational: a surd.`, d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { C.which(m14.map((s) => !V(s).rational), true); C.assert(V(m14[1]).eq(rat(7, 9)) && V(m14[3]).eq(rat(4, 100)), 'the rational ones'); });

const m15 = [r`12\sqrt{3}`, r`18\sqrt{3}`, r`6\sqrt{3}`, r`144\sqrt{3}`];
Q('m15', mk.mcq({ stem: r`A square floor tile has an area of $432$ cm$^2$. Its side, in centimetres and in simplest surd form, is`, opts: O(m15), key: 'a', sol: r`The side is $\sqrt{432}$. Since $432 = 144 \times 3$, $\sqrt{432} = \sqrt{144} \times \sqrt{3} = 12\sqrt{3}$ cm.`, d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { WN(C, m15, sq(432)); C.assert(432 === 144 * 3, '432 = 144 x 3'); });

const m16 = [r`3\sqrt{5}`, r`2\sqrt{11}`, r`4\sqrt{3}`, r`5\sqrt{2}`];
Q('m16', mk.mcq({ stem: r`Four ribbons have lengths $3\sqrt{5}$ m, $2\sqrt{11}$ m, $4\sqrt{3}$ m and $5\sqrt{2}$ m. Which ribbon is the longest?`, opts: O(m16.map((s) => `${s}\\text{ m}`)), key: 'd', sol: r`Compare the squares: $(3\sqrt{5})^2 = 45$, $(2\sqrt{11})^2 = 44$, $(4\sqrt{3})^2 = 48$ and $(5\sqrt{2})^2 = 50$. The largest square belongs to $5\sqrt{2}$.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { const sqs = m16.map((s) => V(s).pow(2)); C.assert(sqs.every((x, i) => x.eq(rat([45, 44, 48, 50][i]))), 'squares 45 44 48 50'); const vs = m16.map((s) => V(s).value); C.which(vs, Math.max(...vs)); });

const m17 = [r`11\sqrt{3}`, r`23\sqrt{3}`, r`11\sqrt{6}`, r`4\sqrt{3}`];
Q('m17', mk.mcq({ stem: r`A craftsman joins pieces of braid of lengths $3\sqrt{48}$ cm and $\sqrt{75}$ cm and then trims off $2\sqrt{27}$ cm. The length that remains, in simplest form, is`, opts: O(m17.map((s) => `${s}\\text{ cm}`)), key: 'a', sol: r`$3\sqrt{48} = 12\sqrt{3}$, $\sqrt{75} = 5\sqrt{3}$ and $2\sqrt{27} = 6\sqrt{3}$. The pieces are like surds, so $12\sqrt{3} + 5\sqrt{3} - 6\sqrt{3} = 11\sqrt{3}$ cm.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { chain([r`3\sqrt{48} + \sqrt{75} - 2\sqrt{27} = 12\sqrt{3} + 5\sqrt{3} - 6\sqrt{3} = 11\sqrt{3}`]); WN(C, m17, r`11\sqrt{3}`); });

const m18 = [r`12\sqrt{15}`, r`6\sqrt{15}`, r`20`, r`12\sqrt{60}`];
Q('m18', mk.mcq({ stem: r`A rectangular banner is $3\sqrt{6}$ m long and $2\sqrt{10}$ m wide. Its area in square metres, in simplest form, is`, opts: O(m18), key: 'a', sol: r`Area $= 3\sqrt{6} \times 2\sqrt{10} = 6\sqrt{60}$. Since $60 = 4 \times 15$, $\sqrt{60} = 2\sqrt{15}$, so the area is $12\sqrt{15}$.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { chain([r`3\sqrt{6} \times 2\sqrt{10} = 6\sqrt{60} = 12\sqrt{15}`]); WN(C, m18, r`12\sqrt{15}`); });

const m19 = [r`5 + 2\sqrt{3}`, r`5 - 2\sqrt{3}`, r`-5 + 2\sqrt{3}`, r`2\sqrt{3}`];
Q('m19', mk.mcq({ stem: r`A rationalising factor of the binomial surd $5 - 2\sqrt{3}$ is`, opts: O(m19), key: 'a', sol: r`The conjugate $5 + 2\sqrt{3}$ works: $(5 - 2\sqrt{3})(5 + 2\sqrt{3}) = 25 - 12 = 13$, which is rational. Each of the other three leaves a surd in the product.`, d: 1, c: 'recall', t: [5], time: 60 }), (C) => { C.which(m19.map((s) => V(s).mul(V(r`5 - 2\sqrt{3}`)).rational), true); chain([r`(5 - 2\sqrt{3})(5 + 2\sqrt{3}) = 25 - 12 = 13`]); });

const m20 = [r`\dfrac{3\sqrt{7} + 3\sqrt{3}}{2}`, r`\dfrac{3\sqrt{7} - 3\sqrt{3}}{2}`, r`6\sqrt{7} + 6\sqrt{3}`, r`\dfrac{3\sqrt{7} + 3\sqrt{3}}{5}`];
Q('m20', mk.mcq({ stem: r`After the denominator is rationalised, $\dfrac{6}{\sqrt{7} - \sqrt{3}}$ becomes`, opts: O(m20), key: 'a', sol: r`Multiply the top and bottom by $\sqrt{7} + \sqrt{3}$. The denominator becomes $7 - 3 = 4$, so the fraction is $\dfrac{6(\sqrt{7} + \sqrt{3})}{4} = \dfrac{3\sqrt{7} + 3\sqrt{3}}{2}$.`, d: 3, c: 'application', t: [5], time: 90 }), (C) => { chain([r`\dfrac{6}{\sqrt{7} - \sqrt{3}} = \dfrac{6(\sqrt{7} + \sqrt{3})}{4} = \dfrac{3\sqrt{7} + 3\sqrt{3}}{2}`]); WN(C, m20, r`\dfrac{6}{\sqrt{7} - \sqrt{3}}`); });

const m21 = [r`4`, r`2\sqrt{5}`, r`-4`, r`1`];
Q('m21', mk.mcq({ stem: r`Two gauges on a machine show the readings $\dfrac{1}{\sqrt{5} - 2}$ and $\dfrac{1}{\sqrt{5} + 2}$. The difference between the first reading and the second is`, opts: O(m21), key: 'a', sol: r`$\dfrac{1}{\sqrt{5} - 2} = \sqrt{5} + 2$ and $\dfrac{1}{\sqrt{5} + 2} = \sqrt{5} - 2$, because $(\sqrt{5} - 2)(\sqrt{5} + 2) = 1$. The difference is $(\sqrt{5} + 2) - (\sqrt{5} - 2) = 4$.`, d: 4, c: 'application', t: [5], time: 105 }), (C) => { chain([r`\dfrac{1}{\sqrt{5} - 2} = \sqrt{5} + 2`]); chain([r`\dfrac{1}{\sqrt{5} + 2} = \sqrt{5} - 2`]); WN(C, m21, r`\dfrac{1}{\sqrt{5} - 2} - \dfrac{1}{\sqrt{5} + 2}`); });

const m22 = [r`1`, r`-1`, r`5`, r`9`];
Q('m22', mk.mcq({ stem: r`If $x = 2 + \sqrt{5}$, then the value of $x^2 - 4x$ is`, opts: O(m22), key: 'a', sol: r`$x^2 = 9 + 4\sqrt{5}$ and $4x = 8 + 4\sqrt{5}$, so $x^2 - 4x = 1$. (Equivalently, $x - 2 = \sqrt{5}$, so $x^2 - 4x + 4 = 5$.)`, d: 4, c: 'analysis', t: [4, 5], time: 105 }), (C) => { chain([r`(2 + \sqrt{5})^2 = 9 + 4\sqrt{5}`]); WN(C, m22, V(r`(2 + \sqrt{5})^2 - 4(2 + \sqrt{5})`)); });

// =============================================================== assertion-reason (ICSE 2027 specimen order a b c d)
Q('ar1', mk.ar({ a: r`The decimal $0.4\overline{5}$ is a rational number.`, r: 'Every non-terminating decimal is an irrational number.', key: 'a', sol: r`$0.4\overline{5} = \dfrac{41}{90}$, which is a quotient of integers, so A is true. R is false: $\dfrac{1}{3} = 0.\overline{3}$ does not terminate, yet it is rational. Option (a).`, d: 2, c: 'understanding', t: [1] }), (C) => { const f = fromRecurring(0, '4', '5'); C.assert(f[0] === 41 && f[1] === 90, '0.4(5) = 41/90'); C.assert(expansion(1, 3).rep === '3' && expansion(1, 3).pre === '', '1/3 recurs: R is false'); C.key('a'); });
Q('ar2', mk.ar({ a: r`$\sqrt{18} + \sqrt{8} = \sqrt{26}$.`, r: r`Square roots of positive numbers obey the product rule $\sqrt{a} \times \sqrt{b} = \sqrt{ab}$.`, key: 'b', sol: r`$\sqrt{18} + \sqrt{8} = 3\sqrt{2} + 2\sqrt{2} = 5\sqrt{2} = \sqrt{50}$, not $\sqrt{26}$: A is false. R is the true product rule. Roots of a sum are not the sum of roots. Option (b).`, d: 2, c: 'understanding', t: [4] }), (C) => { chain([r`\sqrt{18} + \sqrt{8} = 3\sqrt{2} + 2\sqrt{2} = 5\sqrt{2} = \sqrt{50}`]); C.assert(!V(r`\sqrt{18} + \sqrt{8}`).eq(sq(26)) && V(r`\sqrt{12} \times \sqrt{3}`).eq(rat(6)), 'A false, R true'); C.key('b'); });
Q('ar3', mk.ar({ a: r`The product $(4 + \sqrt{7})(4 - \sqrt{7})$ is a rational number.`, r: r`For any numbers $a$ and $b$, $(a + b)(a - b) = a^2 - b^2$.`, key: 'c', sol: r`By R, the product is $4^2 - (\sqrt{7})^2 = 16 - 7 = 9$, which is rational, so A is true. R is a true identity, and it is exactly why the surd disappears. Option (c).`, d: 3, c: 'application', t: [5] }), (C) => { chain([r`(4 + \sqrt{7})(4 - \sqrt{7}) = 4^2 - (\sqrt{7})^2 = 16 - 7 = 9`]); C.key('c'); });
Q('ar4', mk.ar({ a: r`The number $\sqrt{5}$ can be marked on the number line using a right triangle whose perpendicular sides are $2$ and $1$.`, r: r`The number $\sqrt{5}$ is irrational.`, key: 'd', sol: r`The hypotenuse of a right triangle with sides $2$ and $1$ has length $\sqrt{4 + 1} = \sqrt{5}$, so A is true. R is also true, but irrationality is not why the construction works; the Pythagoras relation $2^2 + 1^2 = 5$ is. Option (d).`, d: 3, c: 'analysis', t: [3] }), (C) => { C.assert(near(dist([0, 0], [2, 1]) ** 2, 5) && near(dist([0, 0], [2, 1]), sq(5).value) && !sq(5).rational, 'A true and R true; the reason is Pythagoras'); C.key('d'); });
Q('ar5', mk.ar({ a: r`In the proof that $\sqrt{3}$ is irrational, the step "$3$ divides $p^2$, so $3$ divides $p$" is valid.`, r: 'If a prime divides the product of two integers, it divides at least one of them.', key: 'c', sol: r`Since $p^2 = p \times p$ and $3$ is prime, $3$ must divide one of the two factors $p$, that is, $3$ divides $p$. So A is true, and R is the rule that justifies it. Option (c).`, d: 3, c: 'understanding', t: [2] }), (C) => { const ps = Array.from({ length: 90 }, (_, i) => i + 1); C.assert(ps.every((p) => (p * p % 3 === 0) === (p % 3 === 0)), '3 | p^2 iff 3 | p (1..90)'); C.key('c'); });

// =============================================================== true / false
Q('tf1', mk.tf({ stem: r`Every recurring decimal can be written in the form $\dfrac{p}{q}$, where $p$ and $q$ are integers and $q \ne 0$.`, key: 't', sol: r`If $x$ has a repeating block of $k$ digits, multiplying by $10^k$ shifts the block and subtracting leaves an integer times $x$ on one side and an integer on the other. So $x$ is a fraction.`, d: 1, c: 'recall', t: [1] }), (C) => { const cases = [['0', '', '7'], ['0', '1', '23'], ['3', '', '142857']]; C.assert(cases.every(([i, p, rp]) => { const f = fromRecurring(Number(i), p, rp); const e = expansion(f[0], f[1]); return e.int === Number(i) && ((e.pre + e.rep).length > 0) && e.rep.length > 0; }), 'recurring decimals convert to fractions and back'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`The sum of a rational number and an irrational number is always irrational.`, key: 't', sol: r`Suppose $a$ is rational, $b$ is irrational and $a + b = c$ is rational. Then $b = c - a$ would be rational, which is false. For example, $3 + \sqrt{2}$ is irrational.`, d: 2, c: 'understanding', t: [1] }), (C) => { C.assert(!V(r`3 + \sqrt{2}`).rational && !V(r`\dfrac{1}{2} - \sqrt{7}`).rational, 'examples are irrational'); C.key('t'); }, 'True by contradiction (b = c - a would be rational); examples asserted.');
Q('tf3', mk.tf({ stem: r`Tarun says that $\sqrt{3} + \sqrt{5} = \sqrt{8}$, because $3 + 5 = 8$.`, key: 'f', sol: r`$\sqrt{3} + \sqrt{5} \approx 1.732 + 2.236 = 3.968$, but $\sqrt{8} \approx 2.828$. In general $\sqrt{a} + \sqrt{b} \ne \sqrt{a + b}$; only like surds can be added.`, d: 1, c: 'understanding', t: [4] }), (C) => { C.assert(!V(r`\sqrt{3} + \sqrt{5}`).eq(sq(8)) && Math.abs(V(r`\sqrt{3} + \sqrt{5}`).value - 3.968) < 0.001, 'not equal'); C.key('f'); });
Q('tf4', mk.tf({ stem: r`The number $\sqrt{5}$ is a rationalising factor of $3\sqrt{5}$.`, key: 't', sol: r`$3\sqrt{5} \times \sqrt{5} = 3 \times 5 = 15$, which is rational, so $\sqrt{5}$ rationalises $3\sqrt{5}$. (It is the simplest such factor.)`, d: 2, c: 'understanding', t: [5] }), (C) => { chain([r`3\sqrt{5} \times \sqrt{5} = 15`]); C.key('t'); });
Q('tf5', mk.tf({ stem: r`On the number line, $\sqrt{2}$ lies exactly halfway between $1$ and $2$.`, key: 'f', sol: r`The midpoint is $1.5$, and $1.5^2 = 2.25 \ne 2$. Since $\sqrt{2} \approx 1.414 < 1.5$, $\sqrt{2}$ lies closer to $1$.`, d: 3, c: 'analysis', t: [3] }), (C) => { C.assert(!near(sq(2).value, 1.5) && 1.5 * 1.5 === 2.25 && sq(2).value < 1.5, 'not the midpoint'); C.key('f'); });

// =============================================================== fill in the blanks
Q('fb1', mk.fill({ stem: r`A wooden rod is $\dfrac{7}{16}$ m long. Written as a decimal, its length is ____ m.`, acc: [['0.4375']], sol: r`Long division of $7$ by $16$ ends with remainder $0$ after four digits: $\dfrac{7}{16} = 0.4375$.`, d: 1, c: 'understanding', t: [1] }), (C) => { const e = expansion(7, 16); C.assert(e.int === 0 && e.pre === '4375' && e.rep === '', '0.4375'); C.blank(0.4375); });
Q('fb2', mk.fill({ stem: r`A rectangular sheet has sides $(6 + \sqrt{7})$ cm and $(6 - \sqrt{7})$ cm. Its area, in square centimetres, is ____.`, acc: [['29']], sol: r`Area $= (6 + \sqrt{7})(6 - \sqrt{7}) = 6^2 - (\sqrt{7})^2 = 36 - 7 = 29$.`, d: 2, c: 'understanding', t: [5] }), (C) => { chain([r`(6 + \sqrt{7})(6 - \sqrt{7}) = 36 - 7 = 29`]); C.blank(29); });
Q('fb3', mk.fill({ stem: r`A decimal expansion that neither terminates nor has a repeating block is the expansion of an ____ number. (Write rational or irrational.)`, acc: [['irrational']], sol: r`Rational numbers have terminating or recurring expansions only, so a non-terminating, non-recurring expansion belongs to an irrational number.`, d: 1, c: 'recall', t: [1] }), (C) => { C.blank('irrational'); });
Q('fb4', mk.fill({ stem: r`If $\dfrac{1}{3 + 2\sqrt{2}} = a + b\sqrt{2}$, where $a$ and $b$ are rational numbers, then $b = $ ____.`, acc: [['-2', '−2']], sol: r`Multiply the top and bottom by $3 - 2\sqrt{2}$: the denominator is $9 - 8 = 1$, so $\dfrac{1}{3 + 2\sqrt{2}} = 3 - 2\sqrt{2}$. Hence $a = 3$ and $b = -2$.`, d: 3, c: 'application', t: [5] }), (C) => { const x = chain([r`\dfrac{1}{3 + 2\sqrt{2}} = 3 - 2\sqrt{2}`]); const [a, b] = x.ab(2); C.assert(a[0] === 3 && a[1] === 1 && b[0] === -2 && b[1] === 1, 'a = 3, b = -2'); C.blank(-2); });
Q('fb5', mk.fill({ stem: r`A strip of lace is $\sqrt{98}$ m long. If this length equals $k\sqrt{2}$ m, then $k = $ ____.`, acc: [['7']], sol: r`$98 = 49 \times 2$, so $\sqrt{98} = 7\sqrt{2}$ and $k = 7$.`, d: 1, c: 'understanding', t: [4] }), (C) => { chain([r`\sqrt{98} = 7\sqrt{2}`]); C.blank(7); });

// =============================================================== numerical
Q('n01', mk.num({ stem: r`The recurring decimal $0.\overline{135}$ equals $\dfrac{p}{q}$ in lowest terms. Find $p + q$.`, value: 42, sol: r`Let $x = 0.\overline{135}$. Then $1000x = 135.\overline{135}$, so $999x = 135$ and $x = \dfrac{135}{999} = \dfrac{5}{37}$. Hence $p + q = 5 + 37 = 42$.`, scheme: [['Multiply by 1000 and subtract: 999x = 135', 0.5], ['Lowest terms 5/37, so p + q = 42', 0.5]], d: 3, c: 'application', t: [1], time: 90 }), (C) => { const f = fromRecurring(0, '', '135'); C.assert(f[0] === 5 && f[1] === 37, '5/37'); C.val(f[0] + f[1]); });
Q('n02', mk.num({ stem: r`Find the sum of the digits in the repeating block of the decimal expansion of $\dfrac{3}{13}$.`, value: 27, sol: r`Long division of $3$ by $13$ gives $0.\overline{230769}$ (the remainders $3, 4, 1, 10, 9, 12$ repeat after six steps). The digits add up to $2 + 3 + 0 + 7 + 6 + 9 = 27$.`, scheme: [['Block 230769 found by long division', 0.5], ['Digit sum 27', 0.5]], d: 3, c: 'application', t: [1], time: 120 }), (C) => { const e = expansion(3, 13); C.assert(e.pre === '' && e.rep === '230769', 'block 230769'); C.val([...e.rep].reduce((s, c) => s + Number(c), 0)); });
Q('n03', mk.num({ stem: r`A strip of cloth $\sqrt{288}$ cm long has a piece $\sqrt{162}$ cm long cut off. The strip left is $k\sqrt{2}$ cm long. Find $k$.`, value: 3, sol: r`$\sqrt{288} = 12\sqrt{2}$ and $\sqrt{162} = 9\sqrt{2}$, so the strip left is $12\sqrt{2} - 9\sqrt{2} = 3\sqrt{2}$ cm and $k = 3$.`, scheme: [['Both surds simplified: 12 root 2 and 9 root 2', 0.5], ['Difference 3 root 2, so k = 3', 0.5]], d: 3, c: 'application', t: [4], time: 90 }), (C) => { const x = chain([r`\sqrt{288} - \sqrt{162} = 12\sqrt{2} - 9\sqrt{2} = 3\sqrt{2}`]); C.val(x.part(2)[0] / x.part(2)[1]); });
Q('n04', mk.num({ stem: r`A rectangular courtyard measures $8$ m by $4$ m. Its diagonal is $k\sqrt{5}$ m long. Find $k$.`, value: 4, sol: r`By Pythagoras the diagonal is $\sqrt{8^2 + 4^2} = \sqrt{80} = \sqrt{16 \times 5} = 4\sqrt{5}$ m, so $k = 4$.`, scheme: [['Pythagoras: 64 + 16 = 80', 0.5], ['sqrt 80 = 4 root 5, so k = 4', 0.5]], d: 2, c: 'understanding', t: [3, 4], time: 75 }), (C) => { const x = chain([r`\sqrt{8^2 + 4^2} = \sqrt{80} = 4\sqrt{5}`]); C.val(x.part(5)[0]); });
Q('n05', mk.num({ stem: r`If $\dfrac{\sqrt{5} + \sqrt{3}}{\sqrt{5} - \sqrt{3}} = a + b\sqrt{15}$, where $a$ and $b$ are rational numbers, find $a + b$.`, value: 5, marks: 2, sol: r`Multiply the top and bottom by $\sqrt{5} + \sqrt{3}$. The denominator is $5 - 3 = 2$ and the numerator is $5 + 3 + 2\sqrt{15} = 8 + 2\sqrt{15}$. So the fraction is $4 + \sqrt{15}$, giving $a = 4$, $b = 1$ and $a + b = 5$.`, scheme: [['Multiply by the conjugate: numerator 8 + 2 root 15, denominator 2', 1], ['a = 4, b = 1, so a + b = 5', 1]], d: 4, c: 'application', t: [5], time: 120 }), (C) => { const x = chain([r`\dfrac{\sqrt{5} + \sqrt{3}}{\sqrt{5} - \sqrt{3}} = \dfrac{(\sqrt{5} + \sqrt{3})^2}{2} = \dfrac{8 + 2\sqrt{15}}{2} = 4 + \sqrt{15}`]); const [a, b] = x.ab(15); C.assert(a[1] === 1 && b[1] === 1, 'integers'); C.val(a[0] + b[0]); });
Q('n06', mk.num({ stem: r`A designer scales a drawing by the factor $x = 4 + \sqrt{15}$. Work out $x^2 + \dfrac{1}{x^2}$, the sum of the scale factor squared and its inverse squared.`, value: 62, marks: 2, sol: r`$\dfrac{1}{x} = \dfrac{1}{4 + \sqrt{15}} = 4 - \sqrt{15}$ because $16 - 15 = 1$. So $x + \dfrac{1}{x} = 8$, and $x^2 + \dfrac{1}{x^2} = 8^2 - 2 = 62$.`, scheme: [['1/x = 4 - root 15 by rationalising', 1], ['(x + 1/x) squared minus 2 = 62', 1]], d: 4, c: 'analysis', t: [5], time: 135 }), (C) => { const x = V(r`4 + \sqrt{15}`); const inv = V(r`\dfrac{1}{4 + \sqrt{15}}`); C.assert(inv.eq(V(r`4 - \sqrt{15}`)) && x.add(inv).eq(rat(8)), 'x + 1/x = 8'); const t = x.pow(2).add(inv.pow(2)); C.assert(t.rational, 'rational'); C.val(t.part()[0]); });
Q('n07', mk.num({ stem: r`A rectangular banner measures $3\sqrt{12}$ m by $2\sqrt{27}$ m. Find its area in square metres.`, value: 108, marks: 2, sol: r`$3\sqrt{12} = 6\sqrt{3}$ and $2\sqrt{27} = 6\sqrt{3}$. The area is $6\sqrt{3} \times 6\sqrt{3} = 36 \times 3 = 108$ m$^2$.`, scheme: [['Both sides simplified to 6 root 3', 1], ['Area 36 x 3 = 108', 1]], d: 3, c: 'application', t: [4], time: 105 }), (C) => { const x = chain([r`3\sqrt{12} \times 2\sqrt{27} = 6\sqrt{3} \times 6\sqrt{3} = 108`]); C.val(x.part()[0]); });

// =============================================================== short answer, 2 marks
Q('s201', mk.short({ marks: 2, stem: r`A speedometer label shows the ratio $0.545454\ldots$, that is $0.\overline{54}$. Express it as a fraction in lowest terms.`, model: r`Let $x = 0.\overline{54}$. Then $100x = 54.\overline{54}$.

Subtracting, $99x = 54$, so $x = \dfrac{54}{99} = \dfrac{6}{11}$.`, sol: r`Two digits repeat: multiply by $100$ and subtract.`, scheme: [['100x - x = 54, so 99x = 54', 1], ['x = 6/11 in lowest terms', 1]], d: 2, c: 'understanding', t: [1], time: 120 }), (C) => { const f = fromRecurring(0, '', '54'); C.assert(f[0] === 6 && f[1] === 11, '6/11'); C.model([54, 99, 6, 11]); });
Q('s202', mk.short({ marks: 2, stem: r`Without dividing, decide which of the heights $\dfrac{17}{125}$ m and $\dfrac{17}{150}$ m has a terminating decimal form. Give the reason.`, model: r`$\dfrac{17}{125}$ terminates: $125 = 5^3$ has no prime factor except $5$ (indeed $\dfrac{17}{125} = 0.136$).

$\dfrac{17}{150}$ does not terminate: $150 = 2 \times 3 \times 5^2$ has the prime factor $3$, so its expansion recurs.`, sol: r`Test the prime factors of each denominator in lowest terms.`, scheme: [['17/125 terminates because 125 = 5 cubed', 1], ['17/150 does not: 150 has the factor 3', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { C.assert(terminates(17, 125) && !terminates(17, 150), 'only 17/125 terminates'); const e = expansion(17, 125); C.assert(e.pre === '136' && e.rep === '', '0.136'); C.model([125, 150, 0.136, 3]); });
Q('s203', mk.short({ marks: 2, stem: r`Kabir wants to mark $\sqrt{17}$ and $\sqrt{18}$ on a number line by the right-triangle construction. Give a pair of whole-number perpendicular sides for each, and check each with Pythagoras.`, model: r`$\sqrt{17}$: take sides $4$ and $1$, since $4^2 + 1^2 = 16 + 1 = 17$.

$\sqrt{18}$: take sides $3$ and $3$, since $3^2 + 3^2 = 9 + 9 = 18$.`, sol: r`Write each radicand as a sum of two perfect squares.`, scheme: [['sqrt 17: sides 4 and 1, 16 + 1 = 17', 1], ['sqrt 18: sides 3 and 3, 9 + 9 = 18', 1]], d: 3, c: 'application', t: [3], time: 105 }), (C) => { C.assert(16 + 1 === 17 && 9 + 9 === 18 && near(dist([0, 0], [4, 1]) ** 2, 17) && near(dist([0, 0], [3, 3]) ** 2, 18), 'sums of squares'); C.model([17, 18, 16, 9]); });
Q('s204', mk.short({ marks: 2, stem: r`A florist has two garland wires, one of length $5\sqrt{28}$ cm and one of length $3\sqrt{63}$ cm. Find, in simplest form, by how much the longer wire exceeds the shorter.`, model: r`$5\sqrt{28} = 5 \times 2\sqrt{7} = 10\sqrt{7}$ and $3\sqrt{63} = 3 \times 3\sqrt{7} = 9\sqrt{7}$.

The difference is $10\sqrt{7} - 9\sqrt{7} = \sqrt{7}$ cm.`, sol: r`Simplify each surd to a multiple of $\sqrt{7}$, then subtract.`, scheme: [['Simplify: 10 root 7 and 9 root 7', 1], ['Difference root 7 cm', 1]], d: 2, c: 'understanding', t: [4], time: 90 }), (C) => { chain([r`5\sqrt{28} - 3\sqrt{63} = 10\sqrt{7} - 9\sqrt{7} = \sqrt{7}`]); C.assert(V(r`5\sqrt{28}`).value > V(r`3\sqrt{63}`).value, '5 root 28 is longer'); C.model([10, 9, 7]); });
Q('s205', mk.short({ marks: 2, stem: r`Which is greater, $4\sqrt{6}$ or $3\sqrt{11}$? Show how you decide without using a calculator.`, model: r`Write each as a single root: $4\sqrt{6} = \sqrt{16 \times 6} = \sqrt{96}$ and $3\sqrt{11} = \sqrt{9 \times 11} = \sqrt{99}$.

Since $99 > 96$, $3\sqrt{11}$ is greater.`, sol: r`Compare squares, or bring both under one root sign.`, scheme: [['Both brought under one root: root 96 and root 99', 1], ['99 > 96, so 3 root 11 is greater', 1]], d: 3, c: 'analysis', t: [4], time: 90 }), (C) => { C.assert(V(r`4\sqrt{6}`).pow(2).eq(rat(96)) && V(r`3\sqrt{11}`).pow(2).eq(rat(99)) && V(r`3\sqrt{11}`).value > V(r`4\sqrt{6}`).value, '96 < 99'); C.model([96, 99]); });
Q('s206', mk.short({ marks: 2, stem: r`A rope of length $\dfrac{12}{5\sqrt{6}}$ m is described by a shopkeeper. Rationalise the denominator and write the length in simplest form.`, model: r`Multiply the top and bottom by $\sqrt{6}$: $\dfrac{12}{5\sqrt{6}} = \dfrac{12\sqrt{6}}{5 \times 6} = \dfrac{12\sqrt{6}}{30}$.

In lowest terms this is $\dfrac{2\sqrt{6}}{5}$ m.`, sol: r`A single-term surd denominator is rationalised by that surd.`, scheme: [['Multiply by root 6 over root 6: 12 root 6 / 30', 1], ['Simplest form 2 root 6 / 5', 1]], d: 2, c: 'understanding', t: [5], time: 90 }), (C) => { chain([r`\dfrac{12}{5\sqrt{6}} = \dfrac{12\sqrt{6}}{30} = \dfrac{2\sqrt{6}}{5}`]); C.model([12, 30, 2, 5]); });
Q('s207', mk.short({ marks: 2, stem: r`It is known that $\sqrt{7}$ is irrational. Prove that $4 - \sqrt{7}$ is irrational.`, model: r`Suppose $4 - \sqrt{7} = r$ for some rational number $r$.

Then $\sqrt{7} = 4 - r$, which is rational, since the difference of two rationals is rational. This contradicts the fact that $\sqrt{7}$ is irrational, so $4 - \sqrt{7}$ is irrational.`, sol: r`Proof by contradiction: assume the number is rational and isolate $\sqrt{7}$.`, scheme: [['Assume 4 - root 7 = r, rational, and isolate root 7 = 4 - r', 1], ['4 - r is rational: contradiction', 1]], d: 3, c: 'analysis', t: [2], time: 120 }), null, 'Proof item: assume a rational value, isolate the surd, contradiction with the given irrationality (closure of the rationals under subtraction).');

// =============================================================== short answer, 3 marks
Q('s301', mk.short({ marks: 3, stem: r`A gauge on a water pump reads $2.1333\ldots$, that is $2.1\overline{3}$, units. Express this as a fraction in lowest terms.`, model: r`Let $x = 2.1\overline{3}$. Then $10x = 21.\overline{3}$ and $100x = 213.\overline{3}$.

Subtracting, $90x = 192$.

So $x = \dfrac{192}{90} = \dfrac{32}{15}$.`, sol: r`One digit repeats after one digit that does not: use $10x$ and $100x$.`, scheme: [['10x = 21.333... and 100x = 213.333...', 1], ['90x = 192', 1], ['x = 32/15 in lowest terms', 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => { const f = fromRecurring(2, '1', '3'); C.assert(f[0] === 32 && f[1] === 15 && 213 - 21 === 192, '32/15'); C.assert(expansion(32, 15).int === 2 && expansion(32, 15).pre === '1' && expansion(32, 15).rep === '3', '32/15 = 2.1333...'); C.model([21, 213, 192, 90, 32, 15]); });
Q('s302', mk.short({ marks: 3, stem: r`A square sheet of coloured paper has side $(3\sqrt{2} + 2\sqrt{3})$ dm. Find its area in simplest form.`, model: r`Area $= (3\sqrt{2} + 2\sqrt{3})^2 = (3\sqrt{2})^2 + 2 \times 3\sqrt{2} \times 2\sqrt{3} + (2\sqrt{3})^2$.

$= 18 + 12\sqrt{6} + 12$.

So the area is $30 + 12\sqrt{6}$ dm$^2$.`, sol: r`Expand $(a + b)^2$ with $a = 3\sqrt{2}$ and $b = 2\sqrt{3}$.`, scheme: [['Square expansion: a squared + 2ab + b squared', 1], ['18 + 12 root 6 + 12', 1], ['Area 30 + 12 root 6 square decimetres', 1]], d: 3, c: 'application', t: [4], time: 135 }), (C) => { chain([r`(3\sqrt{2} + 2\sqrt{3})^2 = 18 + 12\sqrt{6} + 12 = 30 + 12\sqrt{6}`]); C.model([18, 12, 30]); });
Q('s303', mk.short({ marks: 3, stem: r`Given that $\sqrt{5} = 2.236$, evaluate $\dfrac{6}{\sqrt{5} + 1}$ correct to three decimal places.`, model: r`Rationalise: $\dfrac{6}{\sqrt{5} + 1} = \dfrac{6(\sqrt{5} - 1)}{5 - 1} = \dfrac{6(\sqrt{5} - 1)}{4} = \dfrac{3(\sqrt{5} - 1)}{2}$.

Substituting $\sqrt{5} = 2.236$: $\dfrac{3 \times 1.236}{2} = \dfrac{3.708}{2} = 1.854$.`, sol: r`Rationalise first; substituting into the original fraction needs a long division.`, scheme: [['Multiply by the conjugate: denominator 5 - 1 = 4', 1], ['Reduce to 3 (root 5 - 1) / 2', 1], ['Substitute 2.236 to get 1.854', 1]], d: 3, c: 'application', t: [5], time: 150 }), (C) => { chain([r`\dfrac{6}{\sqrt{5} + 1} = \dfrac{6(\sqrt{5} - 1)}{4} = \dfrac{3(\sqrt{5} - 1)}{2}`]); C.assert(Math.round(3 * 1236) === 3708 && 3708 / 2 === 1854, '3.708 / 2 = 1.854'); C.model([4, 1.236, 3.708, 1.854]); });
Q('s304', mk.short({ marks: 3, stem: r`A ratio of two rod lengths is $\dfrac{3\sqrt{2} - 2\sqrt{3}}{3\sqrt{2} + 2\sqrt{3}}$. Rationalise the denominator and hence find the rational numbers $a$ and $b$ for which this ratio equals $a - b\sqrt{6}$.`, model: r`Multiply the top and bottom by $3\sqrt{2} - 2\sqrt{3}$. The denominator is $18 - 12 = 6$.

The numerator is $(3\sqrt{2} - 2\sqrt{3})^2 = 18 + 12 - 12\sqrt{6} = 30 - 12\sqrt{6}$.

So the fraction is $\dfrac{30 - 12\sqrt{6}}{6} = 5 - 2\sqrt{6}$, giving $a = 5$ and $b = 2$.`, sol: r`Rationalise with the conjugate, then compare with $a - b\sqrt{6}$.`, scheme: [['Denominator 18 - 12 = 6', 1], ['Numerator 30 - 12 root 6', 1], ['a = 5 and b = 2', 1]], d: 4, c: 'application', t: [5], time: 165 }), (C) => { const x = chain([r`\dfrac{3\sqrt{2} - 2\sqrt{3}}{3\sqrt{2} + 2\sqrt{3}} = \dfrac{(3\sqrt{2} - 2\sqrt{3})^2}{6} = \dfrac{30 - 12\sqrt{6}}{6} = 5 - 2\sqrt{6}`]); const [a, b] = x.ab(6); C.assert(a[0] === 5 && b[0] === -2, 'a = 5, b = 2'); C.model([18, 12, 30, 6, 5, 2]); });
Q('s305', mk.short({ marks: 3, stem: r`It is given that $\sqrt{5}$ is irrational. Use a proof by contradiction to show that the scale factor $\dfrac{3}{\sqrt{5}}$ of a drawing is an irrational number.`, model: r`Suppose $\dfrac{3}{\sqrt{5}} = r$, where $r$ is a rational number. Since $3 \ne 0$, $r \ne 0$.

Then $\sqrt{5} = \dfrac{3}{r}$, which is a quotient of two rational numbers with $r \ne 0$, so it is rational.

This contradicts the fact that $\sqrt{5}$ is irrational. Hence $\dfrac{3}{\sqrt{5}}$ is irrational.`, sol: r`Assume rational, solve for $\sqrt{5}$, and reach a contradiction.`, scheme: [['Assume 3 / root 5 = r, rational and non-zero', 1], ['Root 5 = 3 / r would be rational', 1], ['Contradiction, so 3 / root 5 is irrational', 1]], d: 3, c: 'analysis', t: [2], time: 150 }), (C) => { C.assert(V(r`\dfrac{3}{\sqrt{5}}`).eq(V(r`\dfrac{3\sqrt{5}}{5}`)) && !V(r`\dfrac{3}{\sqrt{5}}`).rational, 'the number is irrational'); C.model([3, 5]); }, 'Proof item: assume r rational (non-zero), then root 5 = 3 / r is rational, a contradiction; the irrationality of 3/root 5 is asserted numerically-exactly.');
Q('s306', mk.short({ marks: 3, stem: r`In the figure, $O$ is $0$ and $A$ is $1$ on the number line. The segment $AB = 1$ is perpendicular to the line at $A$, and the circle with centre $O$ and radius $OB$ meets the line at $P$.

(a) Find $OB$.

(b) State the number that $P$ represents.

(c) Show that $P$ lies between $1.4$ and $1.5$.`, assets: [fig2], model: r`(a) By Pythagoras, $OB^2 = OA^2 + AB^2 = 1 + 1 = 2$, so $OB = \sqrt{2}$.

(b) The circle has radius $OB$, so $OP = OB$ and $P$ represents $\sqrt{2}$.

(c) $1.4^2 = 1.96 < 2$ and $1.5^2 = 2.25 > 2$, so $1.4 < \sqrt{2} < 1.5$.`, sol: r`Pythagoras gives $OB$; the circle copies it on to the line; squares compare $\sqrt{2}$ with $1.4$ and $1.5$.`, scheme: [['(a) OB squared = 1 + 1, so OB = root 2', 1], ['(b) OP = OB, so P is root 2', 1], ['(c) 1.96 < 2 < 2.25', 1]], d: 2, c: 'application', t: [3], time: 150 }), (C) => { C.assert(near(dist([0, 0], [1, 1]), sq(2).value) && 14 * 14 === 196 && 15 * 15 === 225 && 1.4 ** 2 < 2 && 1.5 ** 2 > 2, 'OB = root 2 between 1.4 and 1.5'); C.model([2, 1.96, 2.25]); });

// =============================================================== long answer, 10 marks (3 + 3 + 4)
Q('l01', mk.long({ marks: 10, stem: r`(a) Assume that $\sqrt{2} = \dfrac{p}{q}$, where $p$ and $q$ are integers with no common factor except $1$ and $q \ne 0$. Show that $p$ is even. [3]

(b) Hence show that $q$ is even too, and state the contradiction. [3]

(c) Using the fact that $\sqrt{2}$ is irrational, prove that $7 - 4\sqrt{2}$ is irrational. [4]`, model: r`(a) Squaring $\sqrt{2} = \dfrac{p}{q}$ gives $2 = \dfrac{p^2}{q^2}$, so $p^2 = 2q^2$. Hence $p^2$ is even, and because the square of an odd number is odd, $p$ is even.

(b) Write $p = 2k$. Then $4k^2 = 2q^2$, so $q^2 = 2k^2$ is even and $q$ is even. Now $p$ and $q$ are both divisible by $2$, which contradicts the assumption that they have no common factor. So $\sqrt{2}$ is irrational.

(c) Suppose $7 - 4\sqrt{2} = r$, where $r$ is rational. Then $4\sqrt{2} = 7 - r$, so $\sqrt{2} = \dfrac{7 - r}{4}$. The right side is rational, which contradicts the irrationality of $\sqrt{2}$. Hence $7 - 4\sqrt{2}$ is irrational.`, sol: r`Contradiction proof: parity of $p^2$ and $q^2$, then closure of the rationals.`, scheme: [['(a) p squared = 2 q squared', 1], ['(a) p squared even, so p even', 2], ['(b) p = 2k gives q squared = 2 k squared, so q even', 2], ['(b) common factor 2 contradicts the assumption', 1], ['(c) Assume 7 - 4 root 2 = r, rational, and isolate root 2', 2], ['(c) (7 - r)/4 rational: contradiction', 2]], d: 3, c: 'analysis', t: [2], time: 420 }), null, 'Standard proof of the irrationality of root 2 (parity argument), then a closure argument; every algebraic step is a one-line identity (p squared = 2 q squared; q squared = 2 k squared; root 2 = (7 - r)/4).');
Q('l02', mk.long({ marks: 10, stem: r`(a) Assume $\sqrt{5} = \dfrac{p}{q}$ in lowest terms and show that $5$ divides $p$. [3]

(b) Hence show that $5$ divides $q$ too, and state the contradiction. [3]

(c) Isha tries the same method on $\sqrt{9}$. Show where it breaks down and say what $\sqrt{9}$ really is. [4]`, model: r`(a) Squaring gives $p^2 = 5q^2$, so $5$ divides $p^2$. Because $5$ is prime and $p^2 = p \times p$, $5$ divides $p$.

(b) Write $p = 5k$. Then $25k^2 = 5q^2$, so $q^2 = 5k^2$ and $5$ divides $q^2$, hence $5$ divides $q$. So $5$ is a common factor of $p$ and $q$, which contradicts "lowest terms". Therefore $\sqrt{5}$ is irrational.

(c) For $\sqrt{9} = \dfrac{p}{q}$ we get $p^2 = 9q^2$, so $3$ divides $p$; write $p = 3k$. Then $9k^2 = 9q^2$, so $q = k$, and nothing forces $q$ to be divisible by $3$: there is no common factor and no contradiction. Indeed $p = 3$, $q = 1$ works, because $\sqrt{9} = 3$ is rational.`, sol: r`Prime divisibility drives the proof; for a perfect square the last step does not give a common factor.`, scheme: [['(a) p squared = 5 q squared', 1], ['(a) 5 prime, so 5 divides p', 2], ['(b) p = 5k gives q squared = 5 k squared, so 5 divides q', 2], ['(b) common factor 5 contradicts lowest terms', 1], ['(c) p = 3k gives q = k: no common factor forced', 2], ['(c) root 9 = 3 is rational, p = 3, q = 1', 2]], d: 4, c: 'analysis', t: [2], time: 420 }), (C) => { const k = 1; C.assert(3 * 3 === 9 * 1 * 1 && (3 * k) ** 2 === 9 * k * k, 'p = 3, q = 1 satisfies p squared = 9 q squared'); C.assert(Array.from({ length: 80 }, (_, i) => i + 1).every((p) => (p * p % 5 === 0) === (p % 5 === 0)), '5 | p^2 iff 5 | p'); C.assert(!sq(5).rational && sq(9).rational, 'root 5 irrational, root 9 rational'); }, 'Proof item: parity-style argument with the prime 5; the break-down for root 9 is checked with p = 3, q = 1 and the divisibility fact is asserted for 1..80.');
Q('l03', mk.long({ marks: 10, stem: r`(a) Express $0.\overline{108}$ as a fraction in lowest terms. [3]

(b) Express $0.3\overline{18}$ as a fraction in lowest terms. [3]

(c) State, with a reason, whether each number is rational or irrational: (i) $\sqrt{0.0121}$ (ii) $\sqrt{54}$ (iii) $0.1121231234\ldots$, where the digits $1, 12, 123, 1234, \ldots$ keep growing (iv) $(3 + \sqrt{2})(3 - \sqrt{2})$. [4]`, model: r`(a) Let $x = 0.\overline{108}$. Then $1000x = 108.\overline{108}$, so $999x = 108$ and $x = \dfrac{108}{999} = \dfrac{4}{37}$.

(b) Let $x = 0.3\overline{18}$. Then $10x = 3.\overline{18}$ and $1000x = 318.\overline{18}$. Subtracting, $990x = 315$, so $x = \dfrac{315}{990} = \dfrac{7}{22}$.

(c) (i) $\sqrt{0.0121} = 0.11 = \dfrac{11}{100}$: rational. (ii) $54 = 9 \times 6$, so $\sqrt{54} = 3\sqrt{6}$, and $6$ is not a perfect square: irrational. (iii) The growing blocks never repeat and the decimal never stops: irrational. (iv) $(3 + \sqrt{2})(3 - \sqrt{2}) = 9 - 2 = 7$: rational.`, sol: r`Subtract to remove the repeating part; classify using the expansion or the simplified form.`, scheme: [['(a) 1000x - x = 108', 1], ['(a) 108/999 = 4/37', 2], ['(b) 10x and 1000x, subtract: 990x = 315', 2], ['(b) 315/990 = 7/22', 1], ['(c) (i) rational 11/100 and (iv) rational 7, each with reason', 2], ['(c) (ii) irrational 3 root 6 and (iii) irrational, each with reason', 2]], d: 3, c: 'application', t: [1], time: 450 }), (C) => { const a = fromRecurring(0, '', '108'), b = fromRecurring(0, '3', '18'); C.assert(a[0] === 4 && a[1] === 37 && b[0] === 7 && b[1] === 22, '4/37 and 7/22'); C.assert(1000 * 1 * 108 === 108000 && 318 - 3 === 315 && 990 * 1 === 990, 'working numbers'); C.assert(V(r`\sqrt{0.0121}`).eq(rat(11, 100)) && !V(r`\sqrt{54}`).rational && V(r`(3 + \sqrt{2})(3 - \sqrt{2})`).eq(rat(7)), 'classification (i), (ii), (iv)'); let s = ''; for (let k = 1; s.length < 700; k++) s += Array.from({ length: k }, (_, i) => (i + 1) % 10).join(''); C.assert(hasPeriod(s.slice(0, 600), 100) === 0, '(iii) no repeating block'); C.model([108, 999, 4, 37, 315, 990, 7, 22, 11, 100, 54, 9]); });
Q('l04', mk.long({ marks: 10, stem: r`The figure shows the number line with $O$ at $0$. The segment $AB = 1$ stands at right angles to the line at $A$, which is at $2$, and the circle with centre $O$ and radius $OB$ meets the line at $P$.

(a) Find $OB$ and write down the number that $P$ represents. [3]

(b) Describe how to mark $-\sqrt{5}$ on the same line, and say which two consecutive integers it lies between. [3]

(c) Divya says that $P$ is exactly $2.24$. Use the squares of $2.23$ and $2.24$ to decide whether she is right. [4]`, assets: [fig5], model: r`(a) $OA = 2$ and $AB = 1$ at a right angle, so $OB^2 = 2^2 + 1^2 = 5$ and $OB = \sqrt{5}$. The circle has radius $OB$, so $P$ represents $\sqrt{5}$.

(b) With the same compass opening and centre $O$, cut the line to the left of $O$ at $Q$. Then $OQ = \sqrt{5}$ and $Q$ represents $-\sqrt{5}$. Since $2^2 = 4 < 5 < 9 = 3^2$, we have $2 < \sqrt{5} < 3$, so $-\sqrt{5}$ lies between $-3$ and $-2$.

(c) $2.23^2 = 4.9729$, which is less than $5$, and $2.24^2 = 5.0176$, which is more than $5$. So $2.23 < \sqrt{5} < 2.24$: $P$ lies strictly between them, so $P$ is not exactly $2.24$ and Divya is not right.`, sol: r`Pythagoras for $OB$; reflect the compass arc for the negative; compare squares with $5$.`, scheme: [['(a) OB squared = 4 + 1 = 5', 2], ['(a) P is root 5', 1], ['(b) Cut left of O with the same radius: Q is minus root 5', 2], ['(b) Between minus 3 and minus 2', 1], ['(c) 2.23 squared = 4.9729 and 2.24 squared = 5.0176', 2], ['(c) 4.9729 < 5 < 5.0176, so not exactly 2.24', 2]], d: 3, c: 'application', t: [3], time: 480 }), (C) => { C.assert(near(dist([0, 0], [2, 1]), sq(5).value) && 223 * 223 === 49729 && 224 * 224 === 50176 && 49729 < 50000 && 50176 > 50000, 'OB = root 5; 2.23^2 = 4.9729; 2.24^2 = 5.0176'); C.assert(4 < 5 && 5 < 9, '2 < root 5 < 3'); C.model([5, 4.9729, 5.0176, 2.23, 2.24]); });
Q('l05', mk.long({ marks: 10, stem: r`(a) Simplify $3\sqrt{75} - 2\sqrt{48} + \sqrt{12}$. [3]

(b) Expand and simplify $(3\sqrt{2} + \sqrt{5})(2\sqrt{2} - 3\sqrt{5})$. [3]

(c) A rectangular plot is $5\sqrt{8}$ m long and $3\sqrt{18}$ m wide. Find its perimeter and its area, in simplest form. [4]`, model: r`(a) $3\sqrt{75} = 15\sqrt{3}$, $2\sqrt{48} = 8\sqrt{3}$ and $\sqrt{12} = 2\sqrt{3}$, so the sum is $15\sqrt{3} - 8\sqrt{3} + 2\sqrt{3} = 9\sqrt{3}$.

(b) $(3\sqrt{2})(2\sqrt{2}) = 12$, $(3\sqrt{2})(-3\sqrt{5}) = -9\sqrt{10}$, $(\sqrt{5})(2\sqrt{2}) = 2\sqrt{10}$ and $(\sqrt{5})(-3\sqrt{5}) = -15$. Adding, $12 - 15 - 9\sqrt{10} + 2\sqrt{10} = -3 - 7\sqrt{10}$.

(c) $5\sqrt{8} = 10\sqrt{2}$ m and $3\sqrt{18} = 9\sqrt{2}$ m. Perimeter $= 2(10\sqrt{2} + 9\sqrt{2}) = 38\sqrt{2}$ m. Area $= 10\sqrt{2} \times 9\sqrt{2} = 90 \times 2 = 180$ m$^2$.`, sol: r`Simplify surds to like terms; expand a product term by term; simplify the sides first.`, scheme: [['(a) Each surd simplified: 15, 8 and 2 times root 3', 2], ['(a) Result 9 root 3', 1], ['(b) Four products: 12, minus 9 root 10, 2 root 10, minus 15', 2], ['(b) Result minus 3 minus 7 root 10', 1], ['(c) Perimeter 38 root 2 metres', 2], ['(c) Area 180 square metres', 2]], d: 3, c: 'application', t: [4], time: 450 }), (C) => { chain([r`3\sqrt{75} - 2\sqrt{48} + \sqrt{12} = 15\sqrt{3} - 8\sqrt{3} + 2\sqrt{3} = 9\sqrt{3}`]); chain([r`(3\sqrt{2} + \sqrt{5})(2\sqrt{2} - 3\sqrt{5}) = 12 - 9\sqrt{10} + 2\sqrt{10} - 15 = -3 - 7\sqrt{10}`]); chain([r`2(5\sqrt{8} + 3\sqrt{18}) = 2(10\sqrt{2} + 9\sqrt{2}) = 38\sqrt{2}`]); chain([r`5\sqrt{8} \times 3\sqrt{18} = 10\sqrt{2} \times 9\sqrt{2} = 180`]); C.model([15, 8, 2, 9, 12, 15, 10, 7, 38, 180]); });
Q('l06', mk.long({ marks: 10, stem: r`(a) Rationalise the denominator of $\dfrac{9}{4 - \sqrt{7}}$. [3]

(b) Simplify $\dfrac{1}{\sqrt{7} - \sqrt{6}} - \dfrac{1}{\sqrt{7} + \sqrt{6}}$. [3]

(c) Find rational numbers $a$ and $b$ such that $\dfrac{5 + 2\sqrt{3}}{7 + 4\sqrt{3}} = a - b\sqrt{3}$. [4]`, model: r`(a) Multiply the top and bottom by $4 + \sqrt{7}$. The denominator is $16 - 7 = 9$, so $\dfrac{9}{4 - \sqrt{7}} = \dfrac{9(4 + \sqrt{7})}{9} = 4 + \sqrt{7}$.

(b) $\dfrac{1}{\sqrt{7} - \sqrt{6}} = \sqrt{7} + \sqrt{6}$ and $\dfrac{1}{\sqrt{7} + \sqrt{6}} = \sqrt{7} - \sqrt{6}$, since $7 - 6 = 1$. The difference is $(\sqrt{7} + \sqrt{6}) - (\sqrt{7} - \sqrt{6}) = 2\sqrt{6}$.

(c) Multiply the top and bottom by $7 - 4\sqrt{3}$. The denominator is $49 - 48 = 1$. The numerator is $(5 + 2\sqrt{3})(7 - 4\sqrt{3}) = 35 - 20\sqrt{3} + 14\sqrt{3} - 24 = 11 - 6\sqrt{3}$. So $a = 11$ and $b = 6$.`, sol: r`Conjugate pairs turn each denominator into a rational number.`, scheme: [['(a) Conjugate 4 + root 7, denominator 9', 2], ['(a) Result 4 + root 7', 1], ['(b) Both reciprocals rationalised', 2], ['(b) Difference 2 root 6', 1], ['(c) Conjugate 7 - 4 root 3, denominator 49 - 48 = 1', 2], ['(c) Numerator 11 - 6 root 3, so a = 11 and b = 6', 2]], d: 4, c: 'application', t: [5], time: 480 }), (C) => { chain([r`\dfrac{9}{4 - \sqrt{7}} = \dfrac{9(4 + \sqrt{7})}{9} = 4 + \sqrt{7}`]); chain([r`\dfrac{1}{\sqrt{7} - \sqrt{6}} = \sqrt{7} + \sqrt{6}`]); chain([r`\dfrac{1}{\sqrt{7} + \sqrt{6}} = \sqrt{7} - \sqrt{6}`]); chain([r`\dfrac{1}{\sqrt{7} - \sqrt{6}} - \dfrac{1}{\sqrt{7} + \sqrt{6}} = 2\sqrt{6}`]); const x = chain([r`\dfrac{5 + 2\sqrt{3}}{7 + 4\sqrt{3}} = (5 + 2\sqrt{3})(7 - 4\sqrt{3}) = 35 - 20\sqrt{3} + 14\sqrt{3} - 24 = 11 - 6\sqrt{3}`]); const [a, b] = x.ab(3); C.assert(a[0] === 11 && b[0] === -6, 'a = 11, b = 6'); C.model([16, 9, 4, 6, 49, 48, 35, 24, 11]); });
Q('l07', mk.long({ marks: 10, stem: r`A rectangular rangoli frame has sides $(3 + \sqrt{5})$ cm and $(3 - \sqrt{5})$ cm.

(a) Find its perimeter. [3]

(b) Find its area. [3]

(c) Find the length of its diagonal in simplest form. [4]`, model: r`(a) Perimeter $= 2\{(3 + \sqrt{5}) + (3 - \sqrt{5})\} = 2 \times 6 = 12$ cm.

(b) Area $= (3 + \sqrt{5})(3 - \sqrt{5}) = 3^2 - (\sqrt{5})^2 = 9 - 5 = 4$ cm$^2$.

(c) $(3 + \sqrt{5})^2 = 14 + 6\sqrt{5}$ and $(3 - \sqrt{5})^2 = 14 - 6\sqrt{5}$. By Pythagoras, $d^2 = 14 + 6\sqrt{5} + 14 - 6\sqrt{5} = 28$, so $d = \sqrt{28} = 2\sqrt{7}$ cm.`, sol: r`Conjugate sides: the surd parts cancel in the sum and the product, and in the sum of squares.`, scheme: [['(a) Sum of the two sides is 6', 1], ['(a) Perimeter 12 cm', 2], ['(b) Product of conjugates 9 - 5', 2], ['(b) Area 4 square centimetres', 1], ['(c) Both squares expanded: 14 plus or minus 6 root 5', 2], ['(c) d squared = 28, so d = 2 root 7', 2]], d: 4, c: 'application', t: [4, 5], time: 480 }), (C) => { chain([r`2((3 + \sqrt{5}) + (3 - \sqrt{5})) = 12`]); chain([r`(3 + \sqrt{5})(3 - \sqrt{5}) = 9 - 5 = 4`]); chain([r`(3 + \sqrt{5})^2 = 14 + 6\sqrt{5}`]); chain([r`(3 - \sqrt{5})^2 = 14 - 6\sqrt{5}`]); const d2 = V(r`(3 + \sqrt{5})^2 + (3 - \sqrt{5})^2`); C.assert(d2.eq(rat(28)) && sq(28).eq(V(r`2\sqrt{7}`)), 'd^2 = 28, d = 2 root 7'); C.model([12, 9, 5, 4, 14, 28, 7]); });
